// Serialized into the Dashboard component; only standard browser APIs belong here.
function attachMomentaryButton ({ node, id, endpoint, getSession, canStart, request, onError, state = { seq: 0 } }) {
  if (!state.client) state.client = Array.from(crypto.getRandomValues(new Uint8Array(16)), byte => byte.toString(16).padStart(2, '0')).join('')
  let generation = 0, active = null, timer = null
  const listeners = []
  function listen (target, name, callback) {
    target.addEventListener(name, callback)
    listeners.push(() => target.removeEventListener(name, callback))
  }
  async function transmit (action, session) {
    const options = {
      method: 'POST', credentials: 'same-origin', keepalive: action === 'release',
      priority: 'high',
      headers: { 'Content-Type': 'application/json', 'X-Room-CSRF': session.csrf },
      body: JSON.stringify({ room: session.room, _controlPanel: { kind: 'command', id,
        value: action !== 'release', final: true,
        hold: { client: state.client, seq: ++state.seq, action, epoch: session.holdEpoch } } })
    }
    const parse = async response => {
      if (!response.ok) {
        const error = Error('Momentary command failed (' + response.status + ')')
        error.status = response.status
        throw error
      }
      if (typeof response.json === 'function') {
        const result = await response.json()
        if (action !== 'release' && result.held !== true) throw Error('Momentary hold expired; press again')
      }
    }
    try { return await request(endpoint + '/bound-command', options, 1800, parse) } catch (error) {
      // Only release is retried, with the SAME sequence watermark. A delayed
      // retry cannot cancel a newer press or dispatch a second device command.
      if (action !== 'release' || error.status) throw error
      return request(endpoint + '/bound-command', options, 1800, parse)
    }
  }
  function release () {
    if (!active) return
    const previous = active
    active = null
    generation++
    clearTimeout(timer)
    timer = null
    void transmit('release', previous.session).catch(onError)
    if (previous.pointer !== undefined && node.hasPointerCapture?.(previous.pointer)) {
      try { node.releasePointerCapture(previous.pointer) } catch (_) {}
    }
  }
  function renew (version) {
    if (!active || version !== generation) return
    if (!node.isConnected || !canStart()) { release(); return }
    void transmit('renew', active.session).then(() => {
      if (active && version === generation) timer = setTimeout(() => renew(version), 750)
    }).catch(error => {
      if (active && version === generation) release()
      onError(error)
    })
  }
  function start (source) {
    if (active || node.disabled || !canStart()) return
    const session = getSession()
    if (!session?.csrf) return
    active = { ...source, session: { ...session } }
    const version = ++generation
    void transmit('start', active.session).then(() => {
      if (active && version === generation) timer = setTimeout(() => renew(version), 750)
    }).catch(error => {
      if (active && version === generation) release()
      onError(error)
    })
  }
  listen(node, 'pointerdown', event => {
    if (event.button !== 0 || active) return
    event.preventDefault()
    node.focus()
    start({ pointer: event.pointerId })
    if (active) { try { node.setPointerCapture(event.pointerId) } catch (_) {} }
  })
  const pointerEnd = event => { if (active?.pointer === event.pointerId) release() }
  listen(window, 'pointerup', pointerEnd)
  listen(window, 'pointercancel', pointerEnd)
  listen(node, 'lostpointercapture', pointerEnd)
  listen(node, 'keydown', event => {
    if (![' ', 'Enter'].includes(event.key)) return
    event.preventDefault()
    if (!event.repeat) start({ key: event.key })
  })
  listen(window, 'keyup', event => {
    if (active?.key === event.key) { event.preventDefault(); release() }
  })
  listen(node, 'click', event => event.preventDefault())
  listen(node, 'blur', release)
  listen(window, 'blur', release)
  listen(window, 'pagehide', release)
  listen(document, 'visibilitychange', () => { if (document.hidden) release() })
  return {
    release,
    check () { if (!node.isConnected || node.disabled || !canStart()) release() },
    dispose () { release(); for (const remove of listeners) remove() }
  }
}

module.exports = { attachMomentaryButton }
